import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"configuration.md","filePath":"configuration.md"}`),a={name:`configuration.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>FaultDeck has no config files — everything is passed as CLI flags/args at process start. Values below are the defaults from the source.</p><h2 id="faultdeck-agent" tabindex="-1">faultdeck-agent <a class="header-anchor" href="#faultdeck-agent" aria-label="Permalink to “faultdeck-agent”">​</a></h2><table tabindex="0"><thead><tr><th>flag</th><th>default</th><th>notes</th></tr></thead><tbody><tr><td><code>--bind ADDR</code></td><td><code>127.0.0.1:7000</code></td><td>TCP listen address</td></tr><tr><td><code>--token TOKEN</code></td><td>unset → auth disabled</td><td>when set, every request line must start with <code>&lt;token&gt; </code></td></tr><tr><td><code>--interface IFACE</code></td><td><code>eth0</code></td><td>interface for the <code>tc</code> adapter</td></tr><tr><td><code>--management CIDR</code></td><td>empty</td><td>repeatable; protected networks, overlap rejects injection</td></tr><tr><td><code>--iptables PATH</code></td><td>none</td><td>required for <code>disconnect</code>; without it the agent answers <code>iptables missing</code></td></tr><tr><td><code>--coordinator HOST:PORT</code></td><td>none</td><td>link mode: reverse-dial the coordinator instead of listening</td></tr><tr><td><code>--agent-id ID</code></td><td>none</td><td>registry id; required with <code>--coordinator</code></td></tr><tr><td><code>--heartbeat-ms MS</code></td><td><code>10000</code></td><td>link-mode heartbeat interval (link mode only)</td></tr></tbody></table><p>Behavioral constants (compiled in, not configurable):</p><table tabindex="0"><thead><tr><th>constant</th><th>value</th><th>where</th></tr></thead><tbody><tr><td>max request payload</td><td>64 KiB</td><td><code>faultdeck_agent::MAX_INJECTION_BYTES</code></td></tr><tr><td>pilot qdisc handle</td><td><code>100:</code></td><td><code>faultdeck_netem::PILOT_QDISC_HANDLE</code></td></tr><tr><td>netem qdisc handle</td><td><code>50:</code></td><td>adapter-internal</td></tr><tr><td>max latency</td><td>86 400 000 ms (24 h)</td><td><code>faultdeck_core::MAX_LATENCY_MS</code></td></tr><tr><td>iptables chain</td><td><code>FAULTDECK</code> in table <code>mangle</code></td><td><code>faultdeck_agent::firewall::CHAIN</code></td></tr></tbody></table><p><code>AgentConfig</code> (the library struct behind the flags) also serializes to JSON, so agents can be constructed programmatically.</p><h2 id="faultdeck-coordinator" tabindex="-1">faultdeck-coordinator <a class="header-anchor" href="#faultdeck-coordinator" aria-label="Permalink to “faultdeck-coordinator”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">faultdeck-coordinator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:7001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--token </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">shared-secre</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span></code></pre></div><p><code>--bind</code> defaults to <code>127.0.0.1:7001</code>. <code>--token</code> is optional; when set, every wire message must carry the matching token (see <code>remote-agents.md</code>). State (registry, report archive, live links, per-agent command queues) is in-memory.</p><h2 id="faultdeck-cli" tabindex="-1">faultdeck (CLI) <a class="header-anchor" href="#faultdeck-cli" aria-label="Permalink to “faultdeck (CLI)”">​</a></h2><table tabindex="0"><thead><tr><th>flag</th><th>applies to</th><th>default</th><th>notes</th></tr></thead><tbody><tr><td><code>--host</code></td><td>all <code>remote</code>/<code>hub</code> subcommands</td><td>required</td><td>agent (<code>remote</code>) or coordinator (<code>hub</code>) address</td></tr><tr><td><code>--port</code></td><td>all <code>remote</code>/<code>hub</code> subcommands</td><td><code>7000</code> (<code>remote</code>), <code>7001</code> (<code>hub</code>)</td><td>server port</td></tr><tr><td><code>--token</code></td><td>all <code>remote</code>/<code>hub</code> subcommands</td><td>none</td><td>prefixed to the request line</td></tr><tr><td><code>--agent</code></td><td><code>hub inject</code>/<code>hub rollback</code></td><td>required</td><td>target agent id in the coordinator registry</td></tr><tr><td><code>--fault</code></td><td><code>inject</code></td><td>required</td><td><code>latency</code> | <code>loss</code> | <code>disconnect</code></td></tr><tr><td><code>--destination</code></td><td><code>inject</code></td><td>required</td><td>IPv4 CIDR</td></tr><tr><td><code>--port-spec</code></td><td><code>inject</code></td><td>none</td><td>optional destination-port match</td></tr><tr><td><code>--milliseconds</code></td><td><code>inject --fault latency</code></td><td>required by that fault</td><td>delay</td></tr><tr><td><code>--percent</code></td><td><code>inject --fault loss</code></td><td>required by that fault</td><td>loss percent</td></tr><tr><td><code>--scenario-name</code></td><td><code>inject</code></td><td><code>&quot;scenario&quot;</code></td><td>report label</td></tr><tr><td><code>--report-json</code></td><td><code>remote inject</code></td><td>none</td><td>write JSON report locally</td></tr><tr><td><code>--report-html</code></td><td><code>remote inject</code></td><td>none</td><td>write HTML report locally</td></tr></tbody></table><p>One environment variable exists: <code>FAULTDECK_TIMEOUT_SECS</code> overrides the CLI&#39;s 5-second default read/write timeout on agent connections (<code>crates/cli/src/main.rs</code>). There is no config file lookup, and the agent and coordinator have no options beyond the flags above.</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};